WITH department_stats AS (SELECT dept_id, MIN(hire_date) AS min_hire_date, SUM(CASE WHEN job_title = 'Engineer' THEN 1 ELSE 0 END) AS engineer_count FROM employees WHERE salary > 69000 GROUP BY dept_id) SELECT d.id, d.location, ds.min_hire_date, ds.engineer_count FROM departments d INNER JOIN department_stats ds ON d.id = ds.dept_id ORDER BY min_hire_date, ds.engineer_count DESC;
